"""Repository-check domain module; generated by a mechanical split."""

from __future__ import annotations

from ._shared import *  # noqa: F401,F403

def _check_hash_bound_post_comp1_result(
    relative: str,
    artifact_id: str,
    *,
    required_true_gates: tuple[str, ...],
    required_false_gates: tuple[str, ...],
) -> list[str]:
    """Apply one strict generic integrity contract to the post-COMP1 records."""

    failures: list[str] = []
    result_path = REPOSITORY / relative
    try:
        source = result_path.read_text(encoding="utf-8")
        record = json.loads(source, object_pairs_hook=_reject_duplicate_json_pairs)
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        return [f"cannot parse {artifact_id} result: {exc}"]
    if not isinstance(record, dict):
        return [f"{artifact_id} result must be a JSON object"]
    canonical = json.dumps(record, indent=2, sort_keys=True, allow_nan=False) + "\n"
    if source != canonical:
        failures.append(f"{artifact_id} result JSON is not canonical")
    if (
        record.get("schema_version") != 1
        or record.get("artifact_id") != artifact_id
        or record.get("project_version") != "0.11.0"
    ):
        failures.append(f"{artifact_id} identity, version, or schema has drifted")

    for ledger_name in (
        "source_config_sha256",
        "predecessor_sha256",
        "implementation_sha256",
    ):
        ledger = record.get(ledger_name)
        if ledger is None and ledger_name == "predecessor_sha256":
            continue
        if not isinstance(ledger, dict) or not ledger:
            failures.append(f"{artifact_id} {ledger_name} ledger is absent")
            continue
        for bound_relative, expected in ledger.items():
            if not isinstance(bound_relative, str) or not isinstance(expected, str):
                failures.append(f"{artifact_id} {ledger_name} contains a non-string entry")
                continue
            bound_path = (REPOSITORY / bound_relative).resolve()
            try:
                canonical_relative = bound_path.relative_to(REPOSITORY).as_posix()
            except ValueError:
                failures.append(f"{artifact_id} {ledger_name} escapes the repository")
                continue
            if canonical_relative != bound_relative or not bound_path.is_file():
                failures.append(f"{artifact_id} {ledger_name} path is noncanonical or absent: {bound_relative}")
                continue
            if sha256(bound_path.read_bytes()).hexdigest() != expected:
                failures.append(f"{artifact_id} {ledger_name} is stale for {bound_relative}")

    document = record.get("derivation_document")
    document_hash = record.get("derivation_document_sha256")
    if not isinstance(document, str) or not isinstance(document_hash, str):
        failures.append(f"{artifact_id} derivation-document ledger is absent")
    else:
        document_path = (REPOSITORY / document).resolve()
        try:
            canonical_document = document_path.relative_to(REPOSITORY).as_posix()
        except ValueError:
            canonical_document = ""
        if canonical_document != document or not document_path.is_file():
            failures.append(f"{artifact_id} derivation document is noncanonical or absent")
        elif sha256(document_path.read_bytes()).hexdigest() != document_hash:
            failures.append(f"{artifact_id} derivation-document hash is stale")

    status = record.get("gate_status")
    if not isinstance(status, dict):
        failures.append(f"{artifact_id} gate-status ledger is absent")
    else:
        for name in required_true_gates:
            if status.get(name) is not True:
                failures.append(f"{artifact_id} required gate {name} is not true")
        for name in required_false_gates:
            if status.get(name) is not False:
                failures.append(f"{artifact_id} open gate {name} is not false")
    nonclaims = record.get("nonclaims")
    if not isinstance(nonclaims, dict) or not nonclaims or any(
        value is not False for value in nonclaims.values()
    ):
        failures.append(f"{artifact_id} nonclaim ledger is absent or promoted")
    return failures


def _check_cal7_pref9_result() -> list[str]:
    """Independently enforce CAL7's numerical diagnosis and nonclaim boundary."""

    path = REPOSITORY / "results/fgc-1-cal7-pref9.json"
    try:
        record = json.loads(
            path.read_text(encoding="utf-8"),
            object_pairs_hook=_reject_duplicate_json_pairs,
        )
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        return [f"cannot inspect FGC-1-CAL7-PREF9 certificate: {exc}"]

    failures: list[str] = []
    payload = record.get("artifact_payload", {})
    campaign = payload.get("immutable_campaign", {})
    diagnosis = payload.get("campaign_diagnosis", {})
    raw = payload.get("raw_initial_source_floor", [])
    balanced = payload.get("well_balanced_initial_control", [])
    summary = payload.get("well_balanced_control_summary", {})
    comparison = summary.get("comparison", {})
    hashes = summary.get("well_balanced_input_hashes", [])
    revision = payload.get("prospective_revision", {})
    boundary = payload.get("epistemic_boundary", {})
    status = record.get("gate_status", {})

    expected_order = [
        (amplitude, method, count)
        for amplitude in ("5/2", "3")
        for method in ("RK4", "SSPRK3")
        for count in (2049, 4097, 8193)
    ]

    def ordering(items: object) -> list[tuple[object, object, object]]:
        if not isinstance(items, list):
            return []
        return [
            (item.get("amplitude"), item.get("method"), item.get("point_count"))
            for item in items
            if isinstance(item, dict)
        ]

    raw_primary = [
        item
        for item in raw
        if isinstance(item, dict)
        and item.get("amplitude") == "5/2"
        and item.get("method") == "RK4"
    ] if isinstance(raw, list) else []
    raw_residuals = [item.get("residual_infinity") for item in raw_primary]
    ratios = comparison.get("primary_raw_refinement_ratios", [])
    coefficient_errors = [
        abs(float(item.get("roundoff_coefficient", float("inf"))) - 83.0 / 96.0)
        for item in raw_primary
    ]
    balanced_residuals = [
        item.get("residual_infinity")
        for item in balanced
        if isinstance(item, dict)
    ] if isinstance(balanced, list) else []
    terminals = diagnosis.get("terminal", {})

    expected_true = {
        "PROTO10_campaign_terminated_normally",
        "PROTO10_guarded_common_event_contract_exercised",
        "PROTO10_center_adjacent_binary64_source_floor_localized",
        "PROTO11_well_balanced_reference_map_required",
    }
    expected_false = {
        "PROTO10_GR0_case_eligible",
        "PROTO11_frozen",
        "fresh_GR0_dynamic_calibration_completed",
        "classical_spherical_diagnostic_authorized",
        "FGCQR_holdout_execution_authorized",
        "FGCQR_mechanism_rejected",
        "retained_EFT_evolution_authorized",
        "physical_transition_claim_authorized",
        "general_gradient_route_rejected",
        "singularity_resolution_derived",
        "child_domain_or_topology_derived",
        "dark_sector_mechanism_derived",
        "varying_locally_measured_c_derived",
    }
    revision_true = {
        key for key in revision if key != "new_protocol_required"
    } if isinstance(revision, dict) else set()

    if (
        record.get("classification")
        != "post_calibration_PROTO10_center_adjacent_binary64_source_floor_diagnosis"
        or record.get("generated_by") != "scripts/reproduce_fgc_cal7_pref9.py"
        or record.get("scope_bindings", {}).get("target_protocol")
        != "FGC-2-SF1-PROTO10"
        or record.get("scope_bindings", {}).get("GR0_calibration_trajectory_read")
        is not True
        or record.get("scope_bindings", {}).get("SGBL_trajectory_read") is not False
        or record.get("scope_bindings", {}).get("FGCQR_trajectory_read") is not False
        or record.get("scope_bindings", {}).get("mechanism_question_answered")
        is not False
        or campaign.get("authorization_commit")
        != "9c8aac20954c47b1c844c847fda91e2c423d6c85"
        or campaign.get("campaign_id")
        != "3601547df421a6920d4b9b95d48a9d8ce8f785465f30e9fba9291cc93a510e69"
        or campaign.get("classification")
        != "calibration_failed_no_eligible_GR0_case"
        or campaign.get("manifest_sha256")
        != "ffdd9ac28f023ed65a6dcc8b353a3d3dfd5588b0c1452c140764732fca487c89"
        or campaign.get("event_log_sha256")
        != "9738576d4a2dc0f5d1560531999fcbef910a9b36b7ba999af0e4e75ab6baca92"
        or campaign.get("checkpoint_sha256")
        != "6c646357eba30f6996312c1f24a88863cf893c42c4e3162efe5f4ac7230f2e12"
        or campaign.get("campaign_result_sha256")
        != "3e7e0afb5e353c57669006da213730ed53b9b0f86cc31a0abd375ff8f7cfbac1"
        or diagnosis.get("event_count") != 264
        or diagnosis.get("common_event_count") != 2
        or diagnosis.get("source_only_rejection_count") != 262
        or diagnosis.get("per_amplitude_source_only_rejection_count")
        != {"5/2": 131, "3": 131}
        or diagnosis.get("all_rejections_exactly_rolled_back") is not True
        or diagnosis.get("no_non_source_failure_observed") is not True
        or not isinstance(terminals, dict)
        or set(terminals) != {"5/2", "3"}
        or any(item.get("accepted_step_index") != 15 for item in terminals.values())
        or diagnosis.get("terminal_time_absolute_difference", float("inf")) >= 2.0e-13
        or diagnosis.get("terminal_residual_relative_difference", float("inf"))
        >= 4.0e-11
        or ordering(raw) != expected_order
        or ordering(balanced) != expected_order
        or ordering(hashes) != expected_order
        or len(raw_primary) != 3
        or raw_residuals
        != [
            4.9145872556740196e-14,
            1.9658349022696078e-13,
            7.863339609078496e-13,
        ]
        or any(item.get("maximum_field") != "alpha" for item in raw_primary)
        or any(item.get("maximum_grid_index") != 1 for item in raw_primary)
        or [item.get("maximum_coordinate_radius") for item in raw_primary]
        != [0.0625, 0.03125, 0.015625]
        or len(ratios) != 2
        or any(abs(float(value) - 4.0) >= 1.0e-12 for value in ratios)
        or len(coefficient_errors) != 3
        or max(coefficient_errors, default=float("inf")) >= 1.0e-12
        or len(balanced_residuals) != 12
        or any(
            not isinstance(value, (int, float))
            or not isfinite(value)
            or value < 0.0
            or value >= 1.0e-12
            for value in balanced_residuals
        )
        or comparison.get(
            "all_well_balanced_source_residuals_pass_unchanged_raw_tolerance"
        )
        is not True
        or comparison.get("fine_primary_residual_reduction_factor", 0.0) <= 10.0
        or comparison.get(
            "well_balanced_control_changes_every_primary_projected_input_hash"
        )
        is not True
        or comparison.get("well_balanced_control_is_not_a_runtime_or_campaign_result")
        is not True
        or sum(
            item.get("differs_from_PROTO10_input") is True
            for item in hashes
            if isinstance(item, dict) and item.get("method") == "RK4"
        )
        != 6
        or revision.get("new_protocol_required") != "FGC-2-SF1-PROTO11"
        or not revision_true
        or any(revision.get(key) is not True for key in revision_true)
        or boundary.get("repair_status")
        != "well-balanced t0 control passes, but PROTO11 is not frozen or run"
        or set(status) != expected_true | expected_false
        or any(status.get(key) is not True for key in expected_true)
        or any(status.get(key) is not False for key in expected_false)
        or set(record.get("nonclaims", {})) != expected_false
        or any(value is not False for value in record.get("nonclaims", {}).values())
    ):
        failures.append(
            "FGC-1-CAL7-PREF9 campaign lineage, epsilon/r^2 diagnosis, "
            "well-balanced control, or nonclaim boundary has drifted"
        )
    return failures


