def _check_src2_cap1_contract() -> list[str]:
    """Exercise SRC2's read-only lineage check without opening the raw replay."""

    output_root = REPOSITORY / "runs/fgc-2-sf1/src2/affine-wall-capture"
    existed_before = output_root.exists()
    completed = subprocess.run(
        [sys.executable, "scripts/run_fgc_src2_affine_capture.py", "--check"],
        cwd=REPOSITORY,
        check=False,
        capture_output=True,
        text=True,
    )
    if completed.returncode != 0:
        detail = completed.stderr.strip() or completed.stdout.strip()
        return [f"FGC-1-SRC2-CAP1 contract check failed: {detail}"]
    try:
        record = json.loads(
            completed.stdout,
            object_pairs_hook=_reject_duplicate_json_pairs,
        )
    except (json.JSONDecodeError, ValueError) as exc:
        return [f"cannot parse FGC-1-SRC2-CAP1 contract check: {exc}"]
    if output_root.exists() is not existed_before:
        return ["FGC-1-SRC2-CAP1 --check mutated the raw output namespace"]
    if (
        record.get("artifact_id") != "FGC-1-SRC2-CAP1"
        or record.get("authorized_to_capture") is not True
        or record.get("first_common_event_state_sha256")
        != "212724c1b7615d894d3e0d9ad2488dfe60c8d11957f0fa74c2c61ec324c25e7d"
        or record.get("source_only_rejection_count") != 164
        or record.get("expected_source_only_rejection_count") != 164
        or record.get("terminal_accepted_state_sha256")
        != "414e3805cd2693d73770f6f7222ea27cdaf568299c7f913e6029457320792bab"
        or record.get("terminal_failure_residual") != 1.0659145473163184e-12
        or record.get("output_created_by_check") is not False
        or not isinstance(record.get("output_namespace_exists"), bool)
        or record.get("PROTO12_frozen") is not False
        or record.get("FGCQR_holdout_execution_authorized") is not False
    ):
        return [
            "FGC-1-SRC2-CAP1 replay target, read-only boundary, or nonclaims have drifted"
        ]
    return []


